// Normalize Inputs (drop-in replacement)
const j = $json || {};
function str(x){return (x==null?'':String(x)).trim();}
function url(x){let u = str(x); if(!u) return ''; if(!/^https?:\/\//i.test(u)) u='https://'+u; return u;}
function arr(a){return Array.isArray(a)?a:[];}
function dehash(h){return str(h).replace(/^#/,'').toLowerCase();}

return [{
  json: {
    clientId: str(j.clientId || j.id || ''),
    sheetDocId: str(j.sheetDocId || ''),
    writeKey: str(j.writeKey || ''),
    isTest: !!j.isTest,
    instagram_profile_url: url(j.instagram_profile_url || ''),
    facebook_profile_url: url(j.facebook_profile_url || ''),
    hashtags_ig_in: arr(j.hashtags_ig || []).map(dehash).filter(Boolean),
    hashtags_fb_in: arr(j.hashtags_fb || []).map(dehash).filter(Boolean),
    desiredPlatforms: ['instagram','facebook']
  }
}];

// Validate Trends JSON
function safeParse(s) {
  if (!s || typeof s !== "string") return null;
  const m = s.trim().match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
  const raw = m && m[1] ? m[1].trim() : s.trim();
  try { return JSON.parse(raw); } catch { return null; }
}

function str(x) {
  return (x == null ? '' : String(x)).trim();
}

function arr(a) {
  return Array.isArray(a) ? a : [];
}

function slug(h) {
  return str(h).replace(/^#/, '').toLowerCase();
}

// Fixed path for your actual input structure
const raw =
  $json?.output?.[0]?.content?.find(c => c?.type === 'output_text')?.text ||
  $json?.output?.[0]?.content?.[0]?.text ||
  '';

const parsed = safeParse(raw) || {};

let trends = arr(parsed.trends).map(t => ({
  name: str(t?.name),
  why_trending: str(t?.why_trending),
  how_to_use: str(t?.how_to_use),
  platforms: arr(t?.platforms).map(str).filter(Boolean),
  example_links: arr(t?.example_links).map(str).filter(Boolean),
  hashtags_global: Array.from(new Set(arr(t?.hashtags_global).map(slug).filter(Boolean))).slice(0, 7),
  hashtags_trend_specific: Array.from(new Set(arr(t?.hashtags_trend_specific).map(slug).filter(Boolean))).slice(0, 7)
}));

// Guarantee exactly 10
if (trends.length < 10) {
  trends = trends.concat(
    Array.from({ length: 10 - trends.length }, () => ({
      name: '',
      why_trending: '',
      how_to_use: '',
      platforms: [],
      example_links: [],
      hashtags_global: [],
      hashtags_trend_specific: []
    }))
  );
}

if (trends.length > 10) {
  trends = trends.slice(0, 10);
}

// Union lists
const linkSet = new Set();
const hashSet = new Set();

trends.forEach(t => {
  arr(t.example_links).forEach(l => linkSet.add(l));
  arr(t.hashtags_global).forEach(h => hashSet.add(h));
  arr(t.hashtags_trend_specific).forEach(h => hashSet.add(h));
});

return [
  {
    json: {
      trends,
      trends_text: JSON.stringify({ trends }),
      trend_example_links: Array.from(linkSet),
      trend_hashtags_union: Array.from(hashSet)
    }
  }
];

// Build Trend Research Row (FINAL VERSION)
// Outputs: writeKey, trendsCell, keyCell, clientId, runId, isTest, sheetDocId

function str(x){ return (x==null ? '' : String(x)).trim(); }
function arr(a){ return Array.isArray(a) ? a : []; }
function bullets(a){ if(!Array.isArray(a)||!a.length) return '—'; return a.map(x=>'• '+String(x)).join('\n'); }

// Helper: safe JSON access (preview/run safe)
function J(node){ try { return $node[node].json || {}; } catch(e){ return {}; } }

// Extract text content from LLM node (jsonOutput:true → .message.content)
function getLLM(node){
  const j = J(node);
  return j.message && j.message.content
    ? j.message.content
    : (j.text || j.response || j.content || '');
}

// Parse JSON if stringified
function maybeParse(v){
  if (typeof v === 'string'){
    const s = v.trim();
    if (s.startsWith('{') || s.startsWith('[')){
      try { return JSON.parse(s); } catch { return v; }
    }
    return v;
  }
  return v || {};
}

// === 1) TRENDS ===
const vTrends = J('Validate Trends JSON');
const trendsArr = Array.isArray(vTrends.trends) ? vTrends.trends : [];
const lines = [];
const linkBag = new Set();
const tagSet = new Set();

trendsArr.forEach((t,i)=>{
  const name = str(t.name);
  const why = str(t.why_trending);
  const how = str(t.how_to_use);
  const ex = arr(t.example_links);
  const hG = arr(t.hashtags_global);
  const hS = arr(t.hashtags_trend_specific);
  const tags = Array.from(new Set([...hG, ...hS])).slice(0,7).map(h=>'#'+String(h).toLowerCase());
  tags.forEach(h=>tagSet.add(h));
  ex.forEach(l=>linkBag.add(l));
  lines.push(`${i+1}. ${name}\n   • Why: ${why}\n   • How to use: ${how}\n   • Hashtags: ${tags.join(' ')}`);
});

const trendsCell = lines.join('\n\n');

// === 2) KEY TAKEAWAYS ===
const ktRaw = getLLM('LLM — Key Takeaways JSON');
const ktObj = maybeParse(ktRaw) || {};
const kt = ktObj.key_takeaways || {};
const ktSection = [
  'KEY TAKEAWAYS','',
  'Audience:', bullets(kt.audience), '',
  'Content Themes:', bullets(kt.content_themes), '',
  'Formats:', bullets(kt.formats), '',
  'Posting Behaviors:', bullets(kt.posting_behaviors), '',
  'Hashtag Tips:', bullets(kt.hashtag_tips)
].join('\n');

// === 3) CALENDAR RECOMMENDATIONS ===
const calRaw = getLLM('LLM — Calendar Recs JSON');
const calObj = maybeParse(calRaw) || {};
const cal = Array.isArray(calObj.calendar_recommendations) ? calObj.calendar_recommendations : [];
const calLines = cal.map((c,i)=>[
  `${i+1}. ${str(c.idea)}`,
  `   • Why: ${str(c.rationale)}`,
  `   • Format: ${str(c.suggested_format)}`,
  `   • Platforms: ${arr(c.platforms).join(', ')}`,
  `   • Hashtags: ${arr(c.suggested_hashtags).map(h=>'#'+h).join(' ')}` +
  (arr(c.example_links).length ? `\n   • Examples: ${arr(c.example_links).join(', ')}` : '')
].join('\n'));
const calSection = ['CONTENT CALENDAR RECOMMENDATIONS','', ...calLines].join('\n');

// === 4) STRATEGY ENHANCEMENTS ===
const stRaw = getLLM('LLM — Strategy Enhancements JSON');
const stObj = maybeParse(stRaw) || {};
const st = stObj.strategy_enhancements || {};
const stSection = [
  'ADDITIONAL STRATEGY ENHANCEMENTS','',
  'Creative:', bullets(st.creative), '',
  'Distribution:', bullets(st.distribution), '',
  'Conversion:', bullets(st.conversion)
].join('\n');

// === 5) COMBINE SECTIONS ===
const keyCell = [ktSection, '', calSection, '', stSection].join('\n\n');

// === 6) META FIELDS ===
const runMeta = J('Run Meta');
const normalize = J('Normalize Inputs');
const assembled = J('Assemble Business Inputs');

const writeKey = str(runMeta.writeKey || '');
const runId = str(runMeta.runId || '');
const clientId = str(
  assembled.clientId ||
  normalize.clientId ||
  ''
);
const isTest = !!(J('Start').isTest || normalize.isTest || runMeta.isTest);
const sheetDocId = str(runMeta.sheetDocId || normalize.sheetDocId || assembled.sheetDocId || '');

// === 7) FINAL OUTPUT ===
return [{
  json: {
    writeKey,         // → "Write Key"
    trendsCell,       // → "Chat GPT Trend Search"
    keyCell,          // → "Key Takeaways & Content Calendar Recommendations:"
    clientId,         // → "Client ID"
    runId,            // → "Run ID"
    isTest,           // → "isTest"
    sheetDocId        // retained for reference or downstream operations
  }
}];

// Build Hashtag Inputs from Market research (drop-in replacement)
function arr(a){return Array.isArray(a)?a:[]}
function slug(x){return String(x||'').trim().replace(/^#/,'').toLowerCase()}
function uniq(a){return Array.from(new Set(a))}
function s(x){return String(x||'').trim()}

// n8n Google Sheets returns one item per row -> collect them
const rows = $items('Get Market Research Hashtags').map(i=>i.json);

const igTags = []; const fbTags = [];
const igLinks = []; const fbLinks = [];

for (const r of rows){
  const platform = s(r['Platform'] || r['platform']).toLowerCase();
  const tag = slug(r['Trend Description & Hashtags'] || r['hashtag'] || r['Trend']);
  const link = s(r['Link'] || r['URL'] || r['link']);
  if (!tag) continue;
  if (platform === 'instagram'){ igTags.push(tag); if (link) igLinks.push(link); }
  else if (platform === 'facebook'){ fbTags.push(tag); if (link) fbLinks.push(link); }
}

// Also include any hashtags passed from Start
const fromStartIG = ($item(0).$node['Normalize Inputs']?.json?.hashtags_ig_in) || [];
const fromStartFB = ($item(0).$node['Normalize Inputs']?.json?.hashtags_fb_in) || [];

return [{ json: {
  // carry forward fields the LLM prompts need
  clientId: $item(0).$node['Normalize Inputs']?.json?.clientId || '',
  sheetDocId: $item(0).$node['Normalize Inputs']?.json?.sheetDocId || '',
  writeKey: $item(0).$node['Normalize Inputs']?.json?.writeKey || '',
  instagram_profile_url: $item(0).$node['Normalize Inputs']?.json?.instagram_profile_url || '',
  facebook_profile_url: $item(0).$node['Normalize Inputs']?.json?.facebook_profile_url || '',

  hashtags_ig: uniq([...fromStartIG, ...igTags]).slice(0,50),
  hashtags_fb: uniq([...fromStartFB, ...fbTags]).slice(0,50),
  hashtag_links_ig: uniq(igLinks).slice(0,50),
  hashtag_links_fb: uniq(fbLinks).slice(0,50)
}}];

// Assemble Business Inputs (branch-safe; reads current input only)
function s(x){ return (x==null ? '' : String(x)).trim(); }
function n(x){ const v = Number(x); return Number.isFinite(v) ? v : 0; }
function low(x){ return s(x).toLowerCase(); }
function arr(a){ return Array.isArray(a) ? a : []; }

const inItems = $input.all().map(i => i.json); // <-- read what's actually connected to this node

// Heuristics to separate the two sheet outputs (based on your columns)
const isBizRow = r =>
  'Platform' in r || 'Media type' in r || 'Link to post' in r || '#' in r || 'Time posted' in r;

const isCompRow = r =>
  'What are the trends used most by competitors:' in r;

const bizRows = inItems.filter(isBizRow);
const compRows = inItems.filter(isCompRow);

// --- Find the single summary row (6th line on your sheet design) ---
let summary = bizRows.find(r =>
  s(r['Social Media Tone/Voice/Language']) ||
  s(r['Business Research Ideas Summary']) ||
  s(r['Comment Examples']) ||
  s(r['Post Frequency (last month)#Posts / Frequency']) ||
  s(r['Post Frequency (last 3 months)#Posts / Frequency'])
) || {};

// --- Extract top 5 Instagram posts (rows 1..5) ---
const topIG = bizRows
  .filter(r => low(r['Platform']) === 'instagram')
  .filter(r => [1,2,3,4,5].includes(Number(r['#'] ?? r['Rank'] ?? r['row_number'])))
  .map(r => ({
    rank: Number(r['#'] ?? r['Rank'] ?? 0),
    url: s(r['Link to post']),
    media_type: s(r['Media type']),
    likes: n(r['Likes']),
    comments: n(r['Comments']),
    time_posted: s(r['Time posted']),
  }))
  .sort((a,b) => a.rank - b.rank);

// --- Summaries ---
const out = {
  clientId: s(summary['Client ID'] || summary['clientId']),
  top_ig_posts: topIG,
  tone_voice: s(summary['Social Media Tone/Voice/Language']),
  comment_examples: s(summary['Comment Examples']),
  ideas_summary: s(summary['Business Research Ideas Summary']),
  post_frequency_last_month: s(summary['Post Frequency (last month)#Posts / Frequency']),
  post_frequency_last_3_months: s(summary['Post Frequency (last 3 months)#Posts / Frequency']),
  competitor_trends: s((compRows.find(r => s(r['What are the trends used most by competitors:'])) || {})['What are the trends used most by competitors:'])
};

return [{ json: out }];

// Emit only on first arrival from the merge
if ($runIndex === 0) return [{ json: { ok: true } }];
return [];

